import { useState } from 'react';
import { JxButton, JxInput, JxBadge, JxText, JxCard } from '@jinx-ui/react';

interface RegistrationData {
  fullName: string;
  email: string;
  phone: string;
  street: string;
  city: string;
  zip: string;
}

interface RegistrationFormProps {
  onSubmit: (data: RegistrationData) => void;
}

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const INITIAL_DATA: RegistrationData = {
  fullName: '',
  email: '',
  phone: '',
  street: '',
  city: '',
  zip: '',
};

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [data, setData] = useState<RegistrationData>(INITIAL_DATA);

  const setField = (field: keyof RegistrationData) => (value: string) => {
    setData((prev) => ({ ...prev, [field]: value }));
  };

  const isStepValid = () => {
    if (step === 0) return data.fullName.trim() !== '' && data.email.trim() !== '';
    if (step === 1) return data.street.trim() !== '' && data.city.trim() !== '';
    return true;
  };

  const goBack = () => setStep((prev) => Math.max(prev - 1, 0));
  const goNext = () => setStep((prev) => Math.min(prev + 1, STEPS.length - 1));

  const handlePrimaryAction = () => {
    if (step === STEPS.length - 1) {
      onSubmit(data);
      return;
    }
    goNext();
  };

  return (
    <JxCard style={{ maxWidth: 480, padding: 'var(--jx-space-6)' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--jx-space-3)',
          marginBottom: 'var(--jx-space-6)',
        }}
      >
        {STEPS.map((label, index) => (
          <div
            key={label}
            style={{ display: 'flex', alignItems: 'center', gap: 'var(--jx-space-2)' }}
          >
            <JxBadge variant={index === step ? 'primary' : index < step ? 'success' : 'neutral'}>
              {index + 1}
            </JxBadge>
            <JxText size="sm" tone={index === step ? 'primary' : 'muted'}>
              {label}
            </JxText>
          </div>
        ))}
      </div>

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <JxInput
            label="Полное имя"
            value={data.fullName}
            onValueChange={setField('fullName')}
            required
          />
          <JxInput
            label="Email"
            type="email"
            value={data.email}
            onValueChange={setField('email')}
            required
          />
          <JxInput
            label="Телефон"
            type="tel"
            value={data.phone}
            onValueChange={setField('phone')}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-4)' }}>
          <JxInput
            label="Улица и дом"
            value={data.street}
            onValueChange={setField('street')}
            required
          />
          <JxInput label="Город" value={data.city} onValueChange={setField('city')} required />
          <JxInput label="Почтовый индекс" value={data.zip} onValueChange={setField('zip')} />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-space-3)' }}>
          <JxText weight="medium">Проверьте данные перед отправкой</JxText>
          <JxText size="sm" tone="muted">
            Имя: {data.fullName || '—'}
          </JxText>
          <JxText size="sm" tone="muted">
            Email: {data.email || '—'}
          </JxText>
          <JxText size="sm" tone="muted">
            Телефон: {data.phone || '—'}
          </JxText>
          <JxText size="sm" tone="muted">
            Адрес: {[data.street, data.city, data.zip].filter(Boolean).join(', ') || '—'}
          </JxText>
        </div>
      )}

      <div
        style={{
          display: 'flex',
          justifyContent: 'space-between',
          marginTop: 'var(--jx-space-6)',
        }}
      >
        <JxButton variant="secondary" onClick={goBack} disabled={step === 0}>
          Назад
        </JxButton>
        <JxButton variant="primary" onClick={handlePrimaryAction} disabled={!isStepValid()}>
          {step === STEPS.length - 1 ? 'Отправить' : 'Дальше'}
        </JxButton>
      </div>
    </JxCard>
  );
}

